package com.massifmaps.MassifDemo.examples.camera;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * Flying between places, moving everything in one flight.
 */
@ExampleInfo(
    id = "fly-to",
    title = "Fly to a location",
    description = "One flight moves position, zoom, rotation and tilt together. "
                + "Four separate setters would animate independently and visibly fight.",
    section = Sections.CAMERA,
    order = 10)
public class FlyToExample extends MapExample {

    /** OSM's tile usage policy: a real app identifies itself, or the tiles come back as 403s. */
    private static final String UA = "MassifMapsExamples/1.0 (+https://github.com/massif-maps/MassifMaps)";

    /** name, lon, lat, zoom, rotation, tilt */
    private static final Object[][] PLACES = {
        { "Mont Blanc", 6.8652, 45.8326, 12.5f, 0f, 60f },
        { "Grenoble",   5.7245, 45.1885, 13.5f, 25f, 45f },
        { "Verdon",     6.3320, 43.7500, 13f, -30f, 70f },
    };

    @Override
    public void onStart(ExampleHost host) {
        final MassifMap map = host.map();

        map.addLayer("basemap", Spec.of("raster")
            .set("source", Spec.of("http")
                .set("url", "https://tile.openstreetmap.org/{z}/{x}/{y}.png")
                .set("maxZoom", 19)
                // OSM's tile policy REQUIRES an identifying User-Agent; without one the server
                // answers 403 and every tile comes back as an error image.
                .set("HTTPHeaders", Spec.object().set("User-Agent", UA))));
        map.camera().moveTo(new MapPos(5.7245, 45.1885), 6);

        for (final Object[] place : PLACES) {
            host.button((String) place[0], new Runnable() {
                @Override
                public void run() {
                    // animate(seconds) applies to the next move only, then resets to 0.
                    map.camera().animate(3f).moveTo(
                        new MapPos((Double) place[1], (Double) place[2]),
                        (Float) place[3], (Float) place[4], (Float) place[5]);
                }
            });
        }
        host.button("Stop", new Runnable() {
            @Override
            public void run() {
                map.camera().stop();
            }
        });
        host.caption("Tap a place. Each flight moves all four camera values at once.");
    }
}

package com.massifmaps.MassifDemo.examples.sources;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.MassifSource;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * A GeoJSON document served AS vector tiles, so it goes through the ordinary style and renderer.
 */
@ExampleInfo(
    id = "geojson-line",
    title = "Add a GeoJSON line",
    description = "A \"geojson\" source re-tiles the document on the fly, so the features are "
                + "styled with CartoCSS and drawn by the same renderer as a tile server's.",
    section = Sections.SOURCES,
    order = 10)
public class GeoJsonLineExample extends MapExample {

    /** OSM's tile usage policy: a real app identifies itself, or the tiles come back as 403s. */
    private static final String UA = "MassifMapsExamples/1.0 (+https://github.com/massif-maps/MassifMaps)";

    /** A stretch of the Tour du Mont Blanc, plus the huts along it. */
    private static final String ROUTE =
        "{\"type\":\"FeatureCollection\",\"features\":["
        + "{\"type\":\"Feature\",\"properties\":{\"kind\":\"trail\"},\"geometry\":"
        + "{\"type\":\"LineString\",\"coordinates\":["
        + "[6.8694,45.9237],[6.8290,45.9081],[6.8027,45.8862],[6.7861,45.8548],"
        + "[6.8062,45.8281],[6.8556,45.8090],[6.9016,45.7992],[6.9584,45.8138],"
        + "[6.9821,45.8452],[6.9612,45.8813],[6.9163,45.9096],[6.8694,45.9237]]}},"
        + "{\"type\":\"Feature\",\"properties\":{\"kind\":\"hut\",\"name\":\"Lac Blanc\"},"
        + "\"geometry\":{\"type\":\"Point\",\"coordinates\":[6.8290,45.9081]}},"
        + "{\"type\":\"Feature\",\"properties\":{\"kind\":\"hut\",\"name\":\"Bonhomme\"},"
        + "\"geometry\":{\"type\":\"Point\",\"coordinates\":[6.8062,45.8281]}},"
        + "{\"type\":\"Feature\",\"properties\":{\"kind\":\"hut\",\"name\":\"Elisabetta\"},"
        + "\"geometry\":{\"type\":\"Point\",\"coordinates\":[6.9584,45.8138]}}]}";

    private static final String STYLE = String.join("\n",
        "#tour {",
        "  line-color: #E5484D;",
        "  line-width: linear([view::zoom], (8, 2), (14, 6));",
        "  line-join: round;",
        "  line-cap: round;",
        "}",
        "#tour['kind'='hut'] {",
        "  marker-fill: #FFFFFF;",
        "  marker-line-color: #E5484D;",
        "  marker-line-width: 2;",
        "  marker-width: 9;",
        "}");

    @Override
    public void onStart(ExampleHost host) {
        MassifMap map = host.map();

        map.addLayer("basemap", Spec.of("raster")
            .set("source", Spec.of("http")
                .set("url", "https://tile.openstreetmap.org/{z}/{x}/{y}.png")
                .set("maxZoom", 19)
                // OSM's tile policy REQUIRES an identifying User-Agent; without one the server
                // answers 403 and every tile comes back as an error image.
                .set("HTTPHeaders", Spec.object().set("User-Agent", UA))));

        // The source re-tiles whatever it is given, so an update is one call rather than a rebuild.
        MassifSource tour = map.source("tour-data", Spec.of("geojson").set("maxZoom", 14));
        int layer = tour.createLayer("tour");
        tour.setLayerGeoJSON(layer, ROUTE);

        map.addLayer("tour", Spec.of("vector")
            .set("source", "tour-data")
            .set("style", Spec.of("mbvt")
                .set("cartocss", Spec.of("cartocss").set("css", STYLE))));

        map.camera().moveTo(new MapPos(6.882, 45.866), 10.4f);
        host.caption("One FeatureCollection, tiled on the fly and styled with CartoCSS.");
    }
}

package com.massifmaps.MassifDemo.examples.styles;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.MassifObject;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * A CartoCSS style project, and the two kinds of runtime parameter it can declare.
 */
@ExampleInfo(
    id = "style-parameters",
    title = "Change a style at runtime",
    description = "A style project declares `param::` values the app sets while the map runs. "
                + "A colour swaps live; a parameter used in a filter re-decodes the tiles.",
    section = Sections.STYLES,
    order = 10)
public class StyleParametersExample extends MapExample {

    private static final String[] WATER = { "#8fb8d8", "#2f6f4f", "#7f5af0" };

    private int water;

    @Override
    public void onStart(ExampleHost host) {
        MassifMap map = host.map();

        // The style project is a zip in the assets: alpine.json (which declares the parameters)
        // plus style.mss. See app/src/main/style-projects/alpine.
        //
        // Registered under an id of its own rather than inlined in the layer spec, because the
        // example talks to it afterwards - a layer's style property cannot be read back as a
        // handle. A spec key that is a STRING is looked up in the registry, which is what
        // "style": "alpine" below does.
        final MassifObject style = map.style("alpine", Spec.of("mbvt")
            .set("project", Spec.of("project")
                .set("assets", Spec.of("zip")
                    .set("data", Spec.of("url").set("url", "assets://styles/alpine.zip")))));

        map.addLayer("basemap", Spec.of("vector")
            .set("source", Spec.of("http")
                .set("url", "https://tiles.openfreemap.org/planet/latest/{z}/{x}/{y}.pbf")
                .set("maxZoom", 14)
                .set("HTTPHeaders", Spec.object().set("User-Agent", "MassifMapsExamples/1.0")))
            .set("style", "alpine"));

        map.camera().moveTo(new MapPos(5.7245, 45.1885), 13.5f);

        host.button("Water colour", new Runnable() {
            @Override
            public void run() {
                water = (water + 1) % WATER.length;
                // LIVE: the decoded tiles already point at this value, so it swaps and redraws.
                set(style, "water_color", WATER[water]);
            }
        });
        host.toggle("Buildings", true, new ExampleHost.OnToggle() {
            @Override
            public void onToggle(boolean on) {
                // In a FILTER: this decides what the tile contains, so every tile decodes again.
                set(style, "show_buildings", String.valueOf(on));
            }
        });
        host.caption("Two parameters, two costs: a colour swaps live, a filter re-decodes.");
    }

    private static void set(MassifObject style, String name, String value) {
        MassifObject result = style.call("setStyleParameter", name, value);
        if (result != null) {
            result.close();
        }
    }
}

package com.massifmaps.MassifDemo.examples.terrain;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * The flagship: satellite imagery draped over 3D terrain, with roads and summits on top.
 */
@ExampleInfo(
    id = "terrain-3d",
    title = "3D terrain, hybrid",
    description = "Satellite imagery draped over an elevation mesh, with roads and summit labels "
                + "above it. One DEM source drives the mesh, the hillshade and the elevation "
                + "queries.",
    section = Sections.TERRAIN,
    order = 10)
public class Terrain3DExample extends MapExample {

    /** Identifies the app to the tile servers, which both of them ask for. */
    private static final String UA =
        "MassifMapsExamples/1.0 (+https://github.com/massif-maps/MassifMaps)";

    /**
     * Looking SOUTH at the Matterhorn from high over Zermatt.
     *
     * Composed by hand against three constraints that fight each other: a LOW tilt drops the
     * camera into the slope, a CLOSE zoom hits the terrain's camera clearance and swings the view
     * into a hillside, and a HIGH tilt buries the pyramid in the ridge behind it. This is the
     * window where all three are satisfied and the massif fills the frame.
     */
    private static final MapPos VIEW = new MapPos(7.6586, 45.9763);

    /** Open DEM tiles, terrarium-encoded. */
    private static Spec dem() {
        return Spec.of("http")
            .set("url", "https://tiles.mapterhorn.com/{z}/{x}/{y}.webp")
            .set("minZoom", 1)
            .set("maxZoom", 16)
            // What picks the elevation decoder. Without it the SDK assumes mapbox encoding and
            // every height is wrong.
            .set("encoding", "terrarium");
    }

    @Override
    public void onStart(ExampleHost host) {
        final MassifMap map = host.map();

        // Imagery underneath. The {y}/{x} order is this server's, and the template substitutes by
        // name, so any order works.
        map.addLayer("satellite", Spec.of("raster")
            .set("source", Spec.of("http")
                .set("url", "https://server.arcgisonline.com/ArcGIS/rest/services/"
                          + "World_Imagery/MapServer/tile/{z}/{y}/{x}")
                .set("maxZoom", 18)
                .set("HTTPHeaders", Spec.object().set("User-Agent", UA))));

        // Roads, place names and summits ON TOP, from a style project with no background of its
        // own - see app/src/main/style-projects/hybrid.
        map.style("hybrid", Spec.of("mbvt")
            .set("project", Spec.of("project")
                .set("assets", Spec.of("zip")
                    .set("data", Spec.of("url").set("url", "assets://styles/hybrid.zip")))));
        map.addLayer("labels", Spec.of("vector")
            .set("source", Spec.of("http")
                .set("url", "https://tiles.openfreemap.org/planet/latest/{z}/{x}/{y}.pbf")
                .set("maxZoom", 14)
                .set("HTTPHeaders", Spec.object().set("User-Agent", UA)))
            .set("style", "hybrid"));

        map.terrain(Spec.of("terrain").set("source", dem()))
           .set("exaggeration", 1.25)
           // How far the ground goes on: multiples of the camera-to-focus distance, so one value
           // holds at every zoom. Pair a short one with fog or the ground ends on a hard edge.
           .set("viewDistanceFactor", 1.6)
           // The terrain normally holds the camera 200 m above the ground, which swings a close
           // view into the nearest hillside. Lowered so the camera can sit among the peaks.
           .set("cameraClearance", 40);

        // Options starts with these EMPTY, so they are BUILT here rather than written through.
        map.sky(Spec.of("sky"));
        map.fog(Spec.of("fog").set("rangeStart", 2.2).set("rangeEnd", 8));
        // The sun has to come from BEHIND the camera, or the face being looked at is the one in
        // shadow: this view is of the north side, so the light is north-west. Mid altitude, because
        // a low sun here puts the whole massif in its own shadow.
        map.light(Spec.of("light")
            .set("terrainLightingEnabled", true)
            .set("sunAzimuth", 315)
            .set("sunAltitude", 42)
            .set("shadowStrength", 0.35)
            .set("shadowSoftness", 1.5));

        // tilt 90 is straight down in this SDK, so a landscape view is a LOW tilt.
        map.camera().moveTo(VIEW, 11.5f, 180f, 33f);

        host.toggle("Terrain", true, new ExampleHost.OnToggle() {
            @Override
            public void onToggle(boolean on) {
                map.terrain().set("enabled", on);
            }
        });
        host.toggle("Labels", true, new ExampleHost.OnToggle() {
            @Override
            public void onToggle(boolean on) {
                map.layer("labels").visible(on);
            }
        });
        host.button("Exaggerate", new Runnable() {
            @Override
            public void run() {
                double current = map.terrain().getDouble("exaggeration", 1);
                map.terrain().set("exaggeration", current >= 2 ? 1.0 : current + 0.35);
            }
        });
        host.caption("The Matterhorn. Imagery on the mesh, roads and summits above it.");
    }
}

package com.massifmaps.MassifDemo.examples.annotations;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MapEvents;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.MassifObject;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * Markers and a popup, both described entirely by JSON - no style builder anywhere.
 */
@ExampleInfo(
    id = "markers",
    title = "Markers and popups",
    description = "addMarker takes a spec that carries the position AND the style. "
                + "Tap a summit for a balloon popup; tap the map to dismiss it.",
    section = Sections.ANNOTATIONS,
    order = 10)
public class MarkersExample extends MapExample {

    /** OSM's tile usage policy: a real app identifies itself, or the tiles come back as 403s. */
    private static final String UA = "MassifMapsExamples/1.0 (+https://github.com/massif-maps/MassifMaps)";

    /** name, lon, lat, metres */
    private static final Object[][] SUMMITS = {
        { "Mont Blanc",      6.8652, 45.8326, 4808 },
        { "Grandes Jorasses", 6.9866, 45.8697, 4208 },
        { "Aiguille Verte",  6.9256, 45.9036, 4122 },
        { "Mont Dolent",     7.0575, 45.9264, 3820 },
    };

    private MassifObject popup;

    @Override
    public void onStart(ExampleHost host) {
        final MassifMap map = host.map();

        map.addLayer("basemap", Spec.of("raster")
            .set("source", Spec.of("http")
                .set("url", "https://tile.openstreetmap.org/{z}/{x}/{y}.png")
                .set("maxZoom", 19)
                // OSM's tile policy REQUIRES an identifying User-Agent; without one the server
                // answers 403 and every tile comes back as an error image.
                .set("HTTPHeaders", Spec.object().set("User-Agent", UA))));

        // One style object shared by every marker - what matters once there are thousands of them.
        // A "style" key that is a STRING is looked up by id; an object would be built inline.
        MassifObject pin = map.elements().style("pin", Spec.of("marker")
            .set("size", 26)
            .set("color", 0xFFE5484D)
            .set("clickSize", 40));

        for (Object[] summit : SUMMITS) {
            map.addMarker(Spec.of("marker")
                .set("position", new double[] { (Double) summit[1], (Double) summit[2] })
                .set("style", pin.id()));
        }

        map.camera().moveTo(new MapPos(6.94, 45.87), 10.6f);

        // consumeClick, not onClick: a marker tap has to CLAIM the gesture, or the map's own
        // onClick below fires for the same tap and dismisses the popup as it opens.
        map.elements().consumeClick(new MapEvents.ConsumingHandler<MapEvents.ElementClick>() {
            @Override
            public boolean handle(MapEvents.ElementClick e) {
                show(map, e.position());
                return true;
            }
        });
        map.onClick(new MapEvents.Handler<MapEvents.Click>() {
            @Override
            public void handle(MapEvents.Click e) {
                dismiss(map);
            }
        });
        host.caption("Tap a pin. Everything here - marker, style, popup - is a JSON spec.");
    }

    /** A balloon at a position, built the same way a marker is. */
    private void show(MassifMap map, MapPos position) {
        dismiss(map);
        String name = "Summit";
        int metres = 0;
        for (Object[] summit : SUMMITS) {
            if (near(position, (Double) summit[1], (Double) summit[2])) {
                name = (String) summit[0];
                metres = (Integer) summit[3];
            }
        }
        popup = map.addPopup(Spec.of("balloon")
            .set("position", new double[] { position.getX(), position.getY() })
            .set("title", name)
            .set("description", metres + " m")
            .set("style", Spec.of("balloon")
                .set("cornerRadius", 6)
                .set("leftColor", 0xFFE5484D)
                .set("titleFontSize", 14)
                .set("descriptionFontSize", 12)));
    }

    private void dismiss(MassifMap map) {
        if (popup != null) {
            map.elements().remove(popup);
            popup.close();
            popup = null;
        }
    }

    private static boolean near(MapPos position, double lon, double lat) {
        return Math.abs(position.getX() - lon) < 1e-4 && Math.abs(position.getY() - lat) < 1e-4;
    }
}

package com.massifmaps.MassifDemo.examples.interaction;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MapEvents;
import com.massifmaps.api.MassifLayer;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * Reading the feature under a tap, without parsing a tile.
 */
@ExampleInfo(
    id = "feature-click",
    title = "Get the feature under a tap",
    description = "The click payload is read lazily by path, so asking for one property never "
                + "parses the whole feature - and the geometry is only serialised if you want it.",
    section = Sections.INTERACTION,
    order = 10)
public class FeatureClickExample extends MapExample {

    @Override
    public void onStart(final ExampleHost host) {
        MassifMap map = host.map();

        map.style("alpine", Spec.of("mbvt")
            .set("project", Spec.of("project")
                .set("assets", Spec.of("zip")
                    .set("data", Spec.of("url").set("url", "assets://styles/alpine.zip")))));

        MassifLayer base = map.addLayer("basemap", Spec.of("vector")
            .set("source", Spec.of("http")
                .set("url", "https://tiles.openfreemap.org/planet/latest/{z}/{x}/{y}.pbf")
                .set("maxZoom", 14)
                .set("HTTPHeaders", Spec.object().set("User-Agent", "MassifMapsExamples/1.0")))
            .set("style", "alpine"));

        map.camera().moveTo(new MapPos(5.7245, 45.1885), 14.5f);

        base.onFeatureClick(new MapEvents.Handler<MapEvents.VectorTileClick>() {
            @Override
            public void handle(MapEvents.VectorTileClick e) {
                // Each of these is one read out of the payload. Nothing else is touched.
                String name = e.property("name");
                String kind = e.property("class");
                MapPos where = e.position();
                host.caption(e.layerName()
                             + (name != null ? " - " + name : "")
                             + (kind != null ? " (" + kind + ")" : "")
                             + String.format("  %.5f, %.5f", where.getY(), where.getX()));
            }
        });
        host.caption("Tap a road, a building or the water.");
    }
}

package com.massifmaps.MassifDemo.examples.search;

import com.massifmaps.MassifDemo.examples.ExampleHost;
import com.massifmaps.MassifDemo.examples.ExampleInfo;
import com.massifmaps.MassifDemo.examples.MapExample;
import com.massifmaps.MassifDemo.examples.Sections;
import com.massifmaps.api.MassifMap;
import com.massifmaps.api.MassifObject;
import com.massifmaps.api.Spec;
import com.massifmaps.core.MapPos;

/**
 * Searching the vector tiles the map is already showing, and pinning what comes back.
 */
@ExampleInfo(
    id = "search-features",
    title = "Search the map's own tiles",
    description = "Every filter on a search request is an ordinary property. Runs async, because "
                + "a search fetches and decodes every tile in range.",
    section = Sections.SEARCH,
    order = 10)
public class SearchFeaturesExample extends MapExample {

    private static final MapPos CENTRE = new MapPos(5.7245, 45.1885);
    /** Degrees around the centre. A search with NO geometry scans the whole world at its zoom. */
    private static final double SPAN = 0.08;

    /** The style every result marker shares. */
    private MassifObject hitStyle;

    @Override
    public void onStart(final ExampleHost host) {
        final MassifMap map = host.map();

        map.style("alpine", Spec.of("mbvt")
            .set("project", Spec.of("project")
                .set("assets", Spec.of("zip")
                    .set("data", Spec.of("url").set("url", "assets://styles/alpine.zip")))));

        map.addLayer("basemap", Spec.of("vector")
            .set("source", Spec.of("http")
                .set("url", "https://tiles.openfreemap.org/planet/latest/{z}/{x}/{y}.pbf")
                .set("maxZoom", 14)
                .set("HTTPHeaders", Spec.object().set("User-Agent", "MassifMapsExamples/1.0")))
            .set("style", "alpine"));

        map.camera().moveTo(CENTRE, 13.5f);

        // The service is built FROM THE LAYER: it takes the source and the decoder the layer is
        // already showing, so there is nothing to keep in step.
        final MassifObject service = map.object("search", "poi",
            Spec.of("vectortile").set("layer", "basemap"));
        service.set("minZoom", 14).set("maxZoom", 14).set("maxResults", 12);
        // A struct property: a JSON array, not a call that had to be added for it.
        service.set("layers", new String[] { "place", "poi", "mountain_peak" });

        hitStyle = map.elements().style("hit",
            Spec.of("marker").set("size", 20).set("color", 0xFF3A6EA5));

        host.button("Search \"gare\"", new Runnable() {
            @Override
            public void run() {
                search(host, map, service, "(?i).*gare.*");
            }
        });
        host.button("Search \"parc\"", new Runnable() {
            @Override
            public void run() {
                search(host, map, service, "(?i).*parc.*");
            }
        });
        host.caption("Grenoble. Tap a search - results are pinned as markers.");
    }

    private void search(final ExampleHost host, final MassifMap map, MassifObject service,
                        String regex) {
        map.elements().clear();
        host.caption("Searching...");

        MassifObject request = map.object("search", "request-" + regex.hashCode(),
                                          Spec.of("request"));
        request.set("regexFilter", regex);
        // Bound it, or the search walks every tile in the world at zoom 14.
        request.set("geometry", map.object("geometry", "area", Spec.of("geojson")
            .set("geojson", Spec.object()
                .set("type", "Polygon")
                .set("coordinates", new Object[] { new Object[] {
                    corner(-SPAN, -SPAN), corner(SPAN, -SPAN), corner(SPAN, SPAN),
                    corner(-SPAN, SPAN), corner(-SPAN, -SPAN) } }))));
        request.set("projection", map.object("projection", "wgs84", Spec.of("EPSG:4326")));

        // ASYNC: findFeatures fetches and decodes every tile in range - on the caller's thread
        // that is an ANR, measured at zoom 14 over this camera.
        service.callAsync("findFeatures", new MassifObject.Callback() {
            @Override
            public void onResult(MassifObject found) {
                if (found == null) {
                    host.caption("Search failed.");
                    return;
                }
                int count = (int) found.getLong("featureCount", 0);
                for (int i = 0; i < count; i++) {
                    MassifObject feature = found.call("getFeature", i);
                    try {
                        MapPos at = feature.getPos("geometry.centerPos", "EPSG:4326");
                        if (at != null) {
                            map.addMarker(Spec.of("marker")
                                .set("position", new double[] { at.getX(), at.getY() })
                                .set("style", hitStyle.id()));
                        }
                    } finally {
                        feature.close();
                    }
                }
                host.caption(count + " result" + (count == 1 ? "" : "s") + ".");
            }
        }, request.handle());
    }

    private static double[] corner(double dLon, double dLat) {
        return new double[] { CENTRE.getX() + dLon, CENTRE.getY() + dLat };
    }
}
